    entry = Entry(id="E-9", date="2026-04-02", description="x", amount_cents=1000)
    result = match_entries([entry], [_line(1000)], tolerance_cents=2, period="2026-03")
    assert result.pairs == []
    assert result.unmatched_entries == []


